const navItems=[['brief','⌂','Executive Brief'],['chain','⌘','Chain & Opportunities'],['accounts','◉','Accounts / Characters'],['doctrines','◇','Doctrines'],['inventory','▣','Inventory'],['market','⌁','Market / Trade'],['procurement','⇄','Procurement / Logistics'],['industry','▰','Industry'],['pi','⬡','PI'],['finance','▥','Finance'],['knowledge','◎','Knowledgebase'],['analytics','⌇','Analytics']];
const state={view:'brief',path:[],mode:'relative',category:'All',zoom:1,positions:{J154212:[430,280],J172504:[250,145],J155310:[735,110],J140318:[720,320],J143031:[565,215],Amarr:[580,420]},hidden:new Set(),accountTab:'Roster',knowledgeMode:'Rendered View',marketTab:'Buy Orders',financeRange:'30D'};
const sample='PROTOTYPE · REPRESENTATIVE SAMPLE DATA';
const systems={J154212:{meta:'C4 · Operations HQ',risk:'Home · stable',heat:.72,value:'620M',items:['Frontier Barracks','Instrumental Core Reservoir','K162 → J143031']},J172504:{meta:'C3 · no effect',risk:'No recent activity',heat:.88,value:'480M',items:['Outpost Frontier Stronghold','Ruined Sansha Temple']},J155310:{meta:'C5 · Wolf-Rayet',risk:'Combat probes observed',heat:.98,value:'90M',items:['Core Garrison','Superior Sleeper Cache']},J140318:{meta:'C3 · Black Hole',risk:'Mass reduced',heat:.54,value:'310M',items:['Uncommon Core Deposit']},J143031:{meta:'C2 · route system',risk:'Stable',heat:.42,value:'140M',items:['N968 → J140318']},Amarr:{meta:'High-sec exit',risk:'6 jumps to Market HQ',heat:.35,value:'Route',items:['K162 → Domain']}};
const attention=[{id:1,title:'Doctrine readiness below target',body:'C3 Shield Doctrine has two fitted hulls against a target of four.',target:'doctrines',level:'bad'},{id:2,title:'PI programs approaching expiry',body:'Two extractor programs require intervention within three hours.',target:'pi',level:'warn'},{id:3,title:'Character authorization degraded',body:'Naffin Minner is missing one scope required by inventory reconciliation.',target:'accounts',level:'info'}];
const searchIndex=[['J154212','System · Operations HQ','chain','system','J154212'],['Naffin McGreggor','Character · Account 01','accounts','character','Naffin McGreggor'],['Gas Harvest Support','Corporate skill plan','accounts','skillplan','Gas Harvest Support'],['C3 Shield Doctrine','Doctrine library','doctrines','doctrine','C3 Shield Doctrine'],['PROP-77','Procurement proposal','procurement','proposal','PROP-77'],['PO-1042','Purchase order','procurement','po','PO-1042'],['TL-208','Transport load','procurement','load','TL-208'],['Fullerite-C32','Inventory stack','inventory','inventory','Fullerite-C32'],['Amarr','Market HQ','market','system','Amarr'],['Frontier Barracks','Knowledge entry','knowledge','knowledge','Frontier Barracks'],['Position History','Finance chart','finance','finance','Position History']];
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const panel=(title,body,cls='span-12',extra='')=>`<section class="panel ${cls}"><div class="panel-title"><h2>${title}</h2>${extra}</div>${body}</section>`;
const head=(title,eyebrow='BASTION OPERATIONS')=>`<div class="page-head"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1></div><span class="sample-flag">${sample}</span></div>`;
const tag=(text,cls='')=>`<span class="tag ${cls}">${text}</span>`;
const table=(headers,rows)=>`<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
function renderNav(){$('#nav').innerHTML=navItems.map(([id,icon,label])=>`<button class="nav-btn ${state.view===id?'active':''}" data-nav="${id}"><span class="nav-icon">${icon}</span><span>${label}</span></button>`).join('')}
function mapSvg(){const edges=[['J154212','J172504'],['J154212','J143031'],['J143031','J155310'],['J143031','J140318'],['J154212','Amarr']];const lines=edges.map(([a,b])=>{const p=state.positions[a],q=state.positions[b];return `<line x1="${p[0]}" y1="${p[1]}" x2="${q[0]}" y2="${q[1]}" class="edge ${b==='Amarr'?'route':''}"/>`}).join('');const nodes=Object.entries(state.positions).map(([name,[x,y]])=>{const s=systems[name],r=name==='J154212'?34:26;return `<g class="node ${name==='J154212'?'home':''} ${name==='J155310'?'risk':''}" data-system="${name}" transform="translate(${x} ${y})"><circle r="${r}" style="stroke-width:${2+s.heat*3}px;filter:drop-shadow(0 0 ${5+s.heat*12}px ${state.category==='All'?'#CD8A30':'#3054CD'})"/><text x="${r+10}" y="-7">${name==='Amarr'?'K162 · Amarr':name}</text><text class="meta" x="${r+10}" y="10">${s.meta}</text><text class="value" x="${r+10}" y="27">${s.value}</text></g>`}).join('');return `<svg viewBox="0 0 920 520" style="transform:scale(${state.zoom});transform-origin:center" aria-label="Topological chain graph">${lines}${nodes}</svg>`}
function mapPanel(){return panel('LIVE CHAIN',`<div class="map-stage">${mapSvg()}</div><div class="map-legend"><b>OPPORTUNITY SEMANTICS</b><span>Total</span><span>Capability-covered</span><span>Actionable now</span></div><div class="map-caption">Topology truth · one real system per node · drag nodes to arrange · layout is presentation only</div>`,`map-panel`,`<div class="map-toolbar"><div class="seg"><button class="${state.mode==='relative'?'active':''}" data-mode="relative">Relative</button><button class="${state.mode==='fixed'?'active':''}" data-mode="fixed">Fixed</button></div>${['All','Combat','Gas','Hacking','Ore','Connections'].map(x=>`<button class="chip ${state.category===x?'active':''}" data-cat="${x}">${x}</button>`).join('')}<button class="tiny-btn" data-map="fit">Fit</button><button class="tiny-btn" data-map="reset">Reset</button><button class="tiny-btn" data-map="out">−</button><button class="tiny-btn" data-map="in">+</button></div>`)}
function renderBrief(){const feed=attention.filter(x=>!state.hidden.has(x.id)).map(x=>`<article class="attention-card ${x.level}" data-attention="${x.id}"><h3>${x.title}</h3><p>${x.body}</p><div class="attention-actions"><button data-attention-action="ack" data-id="${x.id}">Acknowledge</button><button data-attention-action="snooze" data-id="${x.id}">Snooze</button><button data-attention-action="defer" data-id="${x.id}">Defer</button></div></article>`).join('');$('#main').innerHTML=`${head('Executive Brief','MAP-FIRST OPERATING PICTURE')}<div class="brief-grid">${mapPanel()}${panel('ATTENTION',`<div class="attention-list">${feed||'<p class="subtle">No unresolved interventions.</p>'}</div>`,'attention','<small>State-backed · may auto-resolve</small>')}${panel('ACTIVE CHARACTERS',`<div class="char-row">${[['Naffin McGreggor','Account 01','Astero · J154212'],['Naffin Minner','Account 02','Prospect · J172504'],['Renab Naf','Account 03 · Alpha','Svipul · J155310'],['Naffin Isktrad','Account 04','Mastodon · Amarr'],['Ollie Henbo','Account 05','Epithal · J154212']].map(c=>`<button class="char-card" data-nav="accounts"><strong>${c[0]}</strong><span>${c[1]}</span><span class="status-pill">● ${c[2]}</span></button>`).join('')}</div>`,'characters','<small>Full canonical names · sample activity</small>')}</div>`}
function renderChain(){renderBrief();$('.page-head h1').textContent='Chain & Opportunities';$('.eyebrow').textContent='TOPOLOGY · CONTENT · VALUE LAYERS'}
function seat(name,stateText,chars){return `<article class="account-card"><div class="account-head"><div><small>ACCOUNT CONTAINER</small><h3>${name}</h3></div>${tag(stateText,stateText==='OMEGA'?'good':'warn')}</div><div class="character-slots">${chars.map(c=>c?`<button class="portrait-seat" data-character="${c[0]}"><span class="portrait">${c[0].split(' ').map(x=>x[0]).join('')}</span><b>${c[0]}</b><small>${c[1]}</small><i>${c[2]}</i></button>`:`<button class="portrait-seat empty" data-action="associate"><span>＋</span><b>Associate Character</b><small>Roster completeness unknown</small></button>`).join('')}</div></article>`}
function renderAccounts(){$('#main').innerHTML=`${head('Accounts / Characters','ROSTER · AUTHORIZATION · TRAINING')}<div class="subnav">${['Roster','Skill Plans','Authorization Health'].map(x=>`<button class="${state.accountTab===x?'active':''}" data-account-tab="${x}">${x}</button>`).join('')}</div><div class="content-grid">${panel('ACCOUNT ROSTER',`<div class="account-grid">${seat('Account 01','OMEGA',[['Naffin McGreggor','ESI healthy · 17d queue','C3 shield eligible'],['Naffin Isktrad','ESI healthy · 8d queue','Trade / hauling'],null])}${seat('Account 02','OMEGA',[['Naffin Minner','Scope gap · 9d queue','Gas / industry'],['Ollie Henbo','Reauthorize required','PI / logistics'],null])}${seat('Account 03','ALPHA',[['Renab Naf','ESI healthy · queue paused','Scout / tackle'],null,null])}</div>`,'span-12')}${panel('CHARACTER-SCOPED ESI CONTROL',`<div class="content-pad">${table(['Character','Health','Scopes','Affected capability','Actions'],[['Naffin McGreggor',tag('HEALTHY','good'),'12 / 12','None','<button class="tiny-btn">View scopes</button> <button class="tiny-btn">Reauthorize</button>'],['Naffin Minner',tag('DEGRADED','warn'),'11 / 12','Inventory reconciliation','<button class="tiny-btn">View scopes</button> <button class="tiny-btn">Reauthorize</button>'],['Ollie Henbo',tag('REAUTH REQUIRED','bad'),'Expired','PI freshness','<button class="tiny-btn">Authorize ESI</button> <button class="danger tiny-btn">Disconnect</button>']])}<p class="subtle">Disconnect removes Bastion authorization; it does not claim provider-side revocation.</p></div>`,'span-7')}${panel('TRAINING & SHARED PLANS',`<div class="content-pad"><h3>Gas Harvest Support</h3><div class="progress"><i style="width:68%"></i></div><div class="kv"><span>Queue-to-plan alignment</span><b>68%</b><span>Next capability</span><b>Sep 22</b><span>Plan milestone</span><b>Oct 06</b><span>Physical skillbooks · Amarr</span><b>18.4M</b><span>Remote injection</span><b>24.9M</b></div><button class="primary" data-action="export">Export corporate skill plan</button></div>`,'span-5')}</div>`}
function renderDoctrines(){const rows=[['C3 Shield Doctrine','PvE · C3',tag('ACTIVE','good'),'4 pilots / 2 ready hulls','2 gaps','<button class="tiny-btn">Open</button>'],['Gas Harvest Support','Harvest',tag('ACTIVE','good'),'3 pilots / 3 hulls','Survey role covered','<button class="tiny-btn">Open</button>'],['Home Defense Response','Defense',tag('DRAFT','warn'),'2 pilots / 1 hull','Evidence review','<button class="tiny-btn">Open</button>']];$('#main').innerHTML=`${head('Doctrines','LIBRARY · FLEET COMPOSITION · READINESS')}<div class="content-grid">${panel('DOCTRINE LIBRARY',table(['Doctrine','Category','Status','Readiness','Gaps','Actions'],rows),'span-12')}${panel('C3 SHIELD DOCTRINE',`<div class="content-pad"><div class="detail-head"><div><h3>Purpose: repeatable C3 combat sites</h3><p class="subtle">Approved: C3 no-effect / Pulsar · Excluded: Wolf-Rayet pending evidence</p></div><button class="primary">Edit doctrine</button></div>${table(['Fleet role','Required','Hull / variant','Eligible pilots','Ready hulls'],[['Anchor / damage','2','Gila · C3 Shield v4','3','2'],['Salvage / utility','1','Noctis · Salvage v2','2','1'],['Scout','Optional','Astero · Chain Scout','4','2']])}<div class="proposal"><b>Readiness proposal:</b> acquire two ready-hull variants. This is a durable proposal, not a purchase order. <button class="tiny-btn" data-nav="procurement">Review promotion</button></div></div>`,'span-8')}${panel('FIT & FIELD EVIDENCE',`<div class="content-pad"><div class="kv"><span>CPU / PG / calibration</span><b>Validated</b><span>Rig-changing alternatives</span><b>Separate ready hulls</b><span>Field confidence</span><b>2 observed runs</b><span>Revision</span><b>v4 · current</b></div><button class="secondary">View revision history</button></div>`,'span-4')}</div>`}
function renderInventory(){const rows=[['Gila “Bastion-03”','Ship','1','Doctrine reserve','Naffin Enterprises'],['Multispectrum Shield Hardener II','Module stack','8','6 doctrine / 2 free','Naffin Enterprises'],['Fullerite-C32','Material stack','18,400','12,400 reaction / 6,000 free','Naffin Enterprises'],['Container: Reaction Inputs','Container','1','Industry staging','Naffin Enterprises']];$('#main').innerHTML=`${head('Inventory','PHYSICAL LOCATION EXPLORER')}<div class="explorer"><aside class="tree panel"><div class="panel-title"><h2>LOCATIONS</h2></div><button class="tree-node active">▾ J154212 <small>Operations HQ</small></button><button class="tree-node indent">▾ Astrahus “Bastion”</button><button class="tree-node indent2">▾ Corporation Hangar 1</button><button class="tree-node indent3">▣ Reaction Inputs</button><button class="tree-node indent2">▸ Corporation Hangar 2</button><button class="tree-node">▸ Amarr</button><button class="tree-node indent">▸ Emperor Family Academy</button></aside><section class="panel contents"><div class="panel-title"><h2>J154212 · AGGREGATED DESCENDANTS</h2><div><button class="tiny-btn" data-action="planmove">Plan Move</button><button class="tiny-btn" data-action="load">Add to Transport Load</button></div></div>${table(['Object / stack','Type','Qty','Purpose / commitment','Custody'],rows)}</section><aside class="panel inspector"><div class="panel-title"><h2>INSPECTOR</h2></div><div class="content-pad"><h3>Fullerite-C32</h3><div class="kv"><span>Physical path</span><b>J154212 › Bastion › Hangar 1 › Reaction Inputs</b><span>Owned</span><b>18,400</b><span>Free</span><b>6,000</b><span>Committed</span><b>12,400</b><span>Liquidatable</span><b>Route-dependent</b></div><p class="subtle">Purpose and liquidity are orthogonal metadata. They do not replace the physical hierarchy.</p></div></aside></div>`}
const marketData={'Buy Orders':[['Shield Extender II','Naffin McGreggor','20 / 8','60%','1.84M','1.86M','-1.1%','14.7M','8.0M','Station','Sep 29','Moderate','Hold','⋯'],['Fuel Block','Naffin Enterprises','40k / 12k','70%','18,120','18,260','-0.8%','217M','120M','Region','Oct 02','Fast','Hold','⋯']],'Sell Orders':[['Fullerite-C32','Naffin Isktrad','18,400 / 7,100','61%','42,800','42,600','41,920','2.1%','304M','292M','Moderate','Review','⋯']],'Contracts':[['TL-208 Courier','Courier · outbound','Naffin Enterprises','Outstanding','Sample Hauler','Reaction outputs · 680M','Amarr / Jita','22,400 m³','Sep 20 / Sep 22','TL-208','Review collateral','⋯']]};
function renderMarket(){const buy=['Item','Issued By','Qty / remaining','Fill','Price','Competing buy','Gap','Remaining value','Escrow','Range','Expiry','Activity','Recommendation','Actions'],sell=['Item','Issued By','Qty / remaining','Sold','Price','Lowest sell','Highest buy','Spread','Listed value','Net proceeds','Activity','Recommendation','Actions'],contracts=['Contract / type','Direction','Issued By','Status','Counterparty','Contents / value','Origin / destination','Volume','Issued / due','Related object','Recommendation','Actions'];$('#main').innerHTML=`${head('Market / Trade','ORDERS · CONTRACTS · ACTIONS')}<div class="summary-strip"><span>Open buys <b>6</b></span><span>Open sells <b>8</b></span><span>Contracts <b>3</b></span><span>Escrow <b>420M</b></span><span>Needs action <b>2</b></span></div><div class="subnav">${Object.keys(marketData).map(x=>`<button class="${state.marketTab===x?'active':''}" data-market-tab="${x}">${x}</button>`).join('')}</div>${panel(state.marketTab,table(state.marketTab==='Buy Orders'?buy:state.marketTab==='Sell Orders'?sell:contracts,marketData[state.marketTab]),'span-12','<small>Explainable sample recommendations</small>')}`}
function renderProcurement(){$('#main').innerHTML=`${head('Procurement / Logistics','REQUIREMENTS · ORDERS · PHYSICAL MOVEMENT')}<div class="content-grid">${panel('APPROVED REQUIREMENTS & PURCHASE ORDERS',table(['Object','Type','Status','Need','Related','Actions'],[['REQ-312','Approved requirement',tag('APPROVED','good'),'2 Gila hulls','C3 Shield Doctrine','Open'],['PO-1042','Purchase order',tag('ACQUIRED','good'),'2 Gila hulls','REQ-312','View loads'],['PO-1048','Purchase order',tag('ORDERED','warn'),'Shield modules','REQ-312','Open']]),'span-7')}${panel('TRANSPORT LOADS',table(['Load','Status','Route','Cargo sources','Capacity','Actions'],[['TL-208',tag('IN TRANSIT','warn'),'Amarr → staging','PO-1042 + PO-1048','22,400 / 62,500 m³','Open'],['TL-211',tag('STAGED','good'),'Home staging','PO-1031','8,100 / 62,500 m³','Open']]),'span-5')}${panel('OBJECT LIFECYCLE',`<div class="content-pad">${table(['Object','Current state','Next valid transition'],[['REQ-312','Approved requirement','Create purchase order'],['PO-1042','Acquired','Assign to transport load'],['TL-208','In transit','Stage / satisfy linked quantities']])}<p class="subtle">One PO may span loads; one load may consolidate compatible items from multiple POs. Bastion plans movement but does not move goods in EVE.</p></div>`,'span-12')}</div>`}
function renderIndustry(){$('#main').innerHTML=`${head('Industry','MAKE · IMPORT · COMMIT')}<div class="content-grid">${panel('MAKE VS IMPORT',table(['Candidate','Inputs','Make','Import','Time','Strategic effect','Action'],[['C3 Shield modules','72%','186M','214M','9h 20m','Closes doctrine gap','<button class="tiny-btn" data-action="procure">Create procurement proposal</button>'],['Fuel Blocks','100%','318M','336M','5h 10m','Restores reserve','<button class="tiny-btn">Create job plan</button>'],['Reaction chain RP-22','84%','620M','681M','22h','Compresses export','<button class="tiny-btn" data-action="procure">Create procurement proposal</button>']]),'span-8')}${panel('PLANNING BASIS',`<div class="content-pad"><div class="kv"><span>Input opportunity value</span><b>Current net realizable</b><span>Historical basis</span><b>Shown separately</b><span>Committed inputs</span><b>Soft constraint</b><span>Forecast vs realized</span><b>Never merged</b></div></div>`,'span-4')}</div>`}
function renderPi(){$('#main').innerHTML=`${head('Planetary Interaction','COLONIES · PROGRAMS · OUTPUT')}<div class="content-grid">${panel('COLONY STATUS',table(['Character','Planet','Program','Ends','Output','Storage','Action'],[['Ollie Henbo','J154212 IV · Barren',tag('ATTENTION','warn'),'2h 48m','Biocells','71%','Open'],['Naffin Minner','J154212 VI · Gas',tag('RUNNING','good'),'1d 8h','Oxidizing Compound','43%','Open'],['Naffin McGreggor','J172504 III · Lava',tag('IDLE','bad'),'—','Consumer Electronics','Needs route','Plan']]),'span-8')}${panel('INDUSTRY LINKS',`<div class="content-pad"><div class="kv"><span>PI output committed</span><b>42%</b><span>Upcoming demand</span><b>Biocells · 8,000</b><span>Projected shortfall</span><b>1,240</b></div><button class="primary" data-nav="industry">Open industry dependency</button></div>`,'span-4')}</div>`}
function renderFinance(){$('#main').innerHTML=`${head('Finance','POSITION · HISTORY · CONTROL')}<div class="kpi-strip"><div><small>LIQUIDITY</small><b>4.28B ISK</b></div><div><small>TOTAL ASSETS</small><b>18.72B ISK</b></div><div><small>LIABILITIES</small><b>1.34B ISK</b></div><div class="emphasis"><small>NET POSITION</small><b>17.38B ISK</b></div></div><div class="subnav">${['7D','30D','90D','1Y','All','Custom'].map(x=>`<button class="${state.financeRange===x?'active':''}" data-finance-range="${x}">${x}</button>`).join('')}</div><div class="content-grid">${panel('POSITION HISTORY',`<div class="position-chart"><svg viewBox="0 0 800 230"><g class="grid-lines"><path d="M50 35H780M50 85H780M50 135H780M50 185H780"/></g><polyline class="series liquidity" points="50,170 170,160 290,168 410,145 530,138 650,120 780,112"/><polyline class="series assets" points="50,95 170,92 290,88 410,80 530,72 650,65 780,57"/><polyline class="series liabilities" points="50,184 170,180 290,178 410,172 530,175 650,168 780,170"/><polyline class="series net" points="50,110 170,106 290,102 410,95 530,84 650,78 780,69"/></svg><div class="chart-key"><span>Liquidity</span><span>Total Assets</span><span>Liabilities</span><strong>Net Position</strong></div></div>`,'span-8')}${panel('FINANCE VIEWS',`<div class="content-pad action-list">${['Overview','Transactions','Liabilities','Receivables','Capital','Forecast'].map(x=>`<button>${x}<span>→</span></button>`).join('')}</div>`,'span-4')}${panel('TRANSACTIONS',table(['Date','Source','Wallet division','Counterparty','Realized amount','Provenance'],[['Sep 17','Market fill','Master Wallet','Sample buyer','+218M','Durable Bastion history'],['Sep 16','Purchase','Procurement','Sample seller','−84M','ESI import · retained'],['Sep 15','Capital contribution','Master Wallet','Owner','+500M','Capital · not revenue']]),'span-12','<small>Wallet Activity · Market Fills</small>')}</div>`}
function renderKnowledge(){const md=`# Frontier Barracks\n\nCurrent operational answer first.\n\n| Field | Current assessment |\n|---|---|\n| Class | C3 combat anomaly |\n| Doctrine | C3 Shield v4 |`;$('#main').innerHTML=`${head('Knowledgebase','SEARCH · EVIDENCE · AUTHORING')}<div class="knowledge-search"><input value="frontier barracks"><button>Search</button></div><div class="facet-row">${['Site','Combat','Sleeper','Field validated','Current','Include superseded'].map(x=>`<button class="chip">${x}</button>`).join('')}</div><div class="content-grid">${panel('RESULTS',`<div class="result-list"><button class="active"><b>Frontier Barracks</b><small>Current answer · 4 observations · 3 sources</small></button><button><b>Instrumental Core Reservoir</b><small>Site mechanics · survey observations</small></button><button><b>C3 Shield execution notes</b><small>Authored note · doctrine-linked</small></button></div>`,'span-4')}${panel('FRONTIER BARRACKS',`<div class="subnav editor-tabs">${['Rendered View','Markdown Edit','Split Edit/Preview'].map(x=>`<button class="${state.knowledgeMode===x?'active':''}" data-knowledge-mode="${x}">${x}</button>`).join('')}<button class="tiny-btn">Revision history</button></div><div class="knowledge-entry ${state.knowledgeMode.includes('Split')?'split':''}">${state.knowledgeMode!=='Rendered View'?`<textarea>${md}</textarea>`:''}<article class="markdown"><h1>Frontier Barracks</h1><p>Current operational answer first: fieldable with the approved C3 Shield doctrine when readiness is green.</p><table><tr><th>Field</th><th>Current assessment</th></tr><tr><td>Class</td><td>C3 combat anomaly</td></tr><tr><td>Doctrine</td><td>C3 Shield v4</td></tr><tr><td>Confidence</td><td>Field validated</td></tr></table><section class="structured-block"><small>STRUCTURED BASTION FACTS · NOT EDITED BY MARKDOWN</small><p>4 observations · 3 sources · 1 open question · revision 6</p></section><h3>Conflicts / uncertainty</h3><blockquote>Trigger ordering remains under review for one wave.</blockquote></article></div>`,'span-8')}</div>`}
function renderAnalytics(){$('#main').innerHTML=`${head('Analytics','HISTORY · COMPARISON · LEARNING')}<div class="analytics-controls"><select><option>Saved: C3 PvE performance by doctrine variant</option><option>Gas ISK per character-hour</option><option>Procurement approval → staged</option></select><button>Period A: Aug 1–31</button><button>Period B: Sep 1–17</button><button>Save view</button></div><div class="content-grid">${panel('REALIZED ISK / CHARACTER-HOUR',`<div class="bar-chart">${[['C3 Shield v3',62],['C3 Shield v4',88],['Gas · dual Prospect',71],['Gas · survey support',93]].map(x=>`<div><span>${x[0]}</span><i style="width:${x[1]}%"></i><b>${x[1]}M</b></div>`).join('')}</div><p class="subtle">Normalized denominator: observed character-hours. Click a cohort to inspect runs.</p>`,'span-7')}${panel('COMPARISON',`<div class="content-pad"><div class="kv"><span>Median completion time</span><b>−11%</b><span>Realized net value</span><b>+18%</b><span>Abort rate</span><b>−4 pp</b><span>Included records</span><b>18 runs</b></div><button class="primary">Drill to underlying events</button></div>`,'span-5')}${panel('SAVED ANALYTICAL VIEWS',table(['View','Question','Last range','Action'],[['PI output and tax burden','Which planets create avoidable tax?','90D','Open'],['Market fills by item','Median time-to-fill and realized margin','30D','Open'],['Transport efficiency','Exit + Market HQ route efficiency','All','Open']]),'span-12')}</div>`}
