function navigate(view,label){if(state.view!==view)state.path.push({view:state.view,label:label||navItems.find(x=>x[0]===state.view)?.[2]});state.view=view;closeDrawer();render();$('#main').focus()}
function openDrawer(title,body,target){const prior=state.trail?.at(-2),current=state.trail?.at(-1);$('#drawer').innerHTML=`<div class="drawer-head"><div><div class="bread">${prior?`<button data-trail-back>${prior.label}${prior.object?` · ${prior.object}`:''}</button><span>›</span>`:''}<span>${current?.label||state.path.at(-1)?.label||'Executive Brief'}</span><span>›</span><span>${title}</span></div><h2>${title}</h2></div><button class="drawer-close" data-close>×</button></div><div class="drawer-body">${body}</div><div class="drawer-actions"><button class="secondary" data-close>Close</button><button class="primary" data-full-view="${target}" data-full-id="${title}">Open Full View →</button></div>`;$('#drawer').classList.add('open');$('#drawer').setAttribute('aria-hidden','false');$('#scrim').classList.add('open');bindDynamic()}
function closeDrawer(){$('#drawer').classList.remove('open');$('#drawer').setAttribute('aria-hidden','true');$('#scrim').classList.remove('open')}
function bindMapDrag(){const svg=$('.map-stage svg');if(!svg)return;let drag=null;$$('.node').forEach(n=>n.addEventListener('pointerdown',e=>{e.preventDefault();drag={n,name:n.dataset.system,start:[e.clientX,e.clientY],pos:[...state.positions[n.dataset.system]]};n.setPointerCapture(e.pointerId)}));svg.addEventListener('pointermove',e=>{if(!drag)return;const scale=920/svg.getBoundingClientRect().width,x=drag.pos[0]+(e.clientX-drag.start[0])*scale/state.zoom,y=drag.pos[1]+(e.clientY-drag.start[1])*scale/state.zoom;state.positions[drag.name]=[x,y];drag.n.setAttribute('transform',`translate(${x} ${y})`)});svg.addEventListener('pointerup',()=>drag=null)}
function bindDynamic(){$$('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav,b.textContent.trim()));$$('[data-close]').forEach(b=>b.onclick=closeDrawer);$$('[data-mode]').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;render()});$$('[data-cat]').forEach(b=>b.onclick=()=>{state.category=b.dataset.cat;render()});$$('[data-map]').forEach(b=>b.onclick=()=>{if(b.dataset.map==='in')state.zoom=Math.min(1.5,state.zoom+.1);if(b.dataset.map==='out')state.zoom=Math.max(.7,state.zoom-.1);if(['fit','reset'].includes(b.dataset.map)){state.zoom=1;if(b.dataset.map==='reset')state.positions={J154212:[430,280],J172504:[250,145],J155310:[735,110],J140318:[720,320],J143031:[565,215],Amarr:[580,420]}}render()});$$('[data-system]').forEach(n=>n.onclick=()=>{const s=systems[n.dataset.system];openDrawer(n.dataset.system,`<div class="drawer-tabs">${['All','Combat','Gas','Connections'].map(x=>`<button class="chip">${x}</button>`).join('')}</div><div class="drawer-section"><h3>SYSTEM SNAPSHOT</h3><div class="kv"><span>Classification</span><b>${s.meta}</b><span>Risk / activity</span><b>${s.risk}</b><span>Opportunity</span><b>${s.value}</b></div></div><div class="drawer-section"><h3>CURRENT CONTENT</h3>${s.items.map(x=>`<button class="content-card"><b>${x}</b><small>Open contextual detail</small></button>`).join('')}</div><div class="drawer-section"><h3>SOURCE</h3><p class="subtle">Nexum-backed sample topology. Presentation layout is independent of topology truth.</p></div>`,'chain')});$$('[data-attention]').forEach(x=>x.onclick=e=>{if(e.target.closest('button'))return;const a=attention.find(y=>y.id==x.dataset.attention);openDrawer(a.title,`<p>${a.body}</p><p class="subtle">Acknowledgement, snooze, and defer preserve the source condition. The item auto-resolves when that condition clears.</p>`,a.target)});$$('[data-attention-action]').forEach(b=>b.onclick=e=>{e.stopPropagation();state.hidden.add(+b.dataset.id);toast(`${b.dataset.attentionAction} recorded · source will be reevaluated`);render()});$$('[data-account-tab]').forEach(b=>b.onclick=()=>{state.accountTab=b.dataset.accountTab;render()});$$('[data-market-tab]').forEach(b=>b.onclick=()=>{state.marketTab=b.dataset.marketTab;render()});$$('[data-finance-range]').forEach(b=>b.onclick=()=>{state.financeRange=b.dataset.financeRange;render()});$$('[data-knowledge-mode]').forEach(b=>b.onclick=()=>{state.knowledgeMode=b.dataset.knowledgeMode;render()});$$('[data-character]').forEach(b=>b.onclick=()=>openDrawer(b.dataset.character,`<div class="kv"><span>Account</span><b>Account 01</b><span>Queue</span><b>17d 4h</b><span>Next milestone</span><b>Sep 26</b><span>Doctrine links</span><b>C3 Shield · Scout</b></div><h3>SKILLBOOK SOURCING</h3><p>Physical: 18.4M · remote injection: 24.9M</p>`,'accounts'));$$('[data-action]').forEach(b=>b.onclick=()=>toast(`${b.dataset.action} · sample interaction only`));bindMapDrag()}
function render(){renderNav();(renders[state.view]||renderBrief)();bindDynamic()}

