function enhancedMapSvg(cls=''){
 const edges=[['J154212','J172504','H296 · stable'],['J154212','J143031','K162 · reduced'],['J143031','J155310','N110 · stable'],['J143031','J140318','Z647 · critical'],['J154212','Amarr','K162 · high-sec']];
 const lines=edges.map(([a,b,l])=>{const p=state.positions[a],q=state.positions[b],mx=(p[0]+q[0])/2,my=(p[1]+q[1])/2;return `<g><line x1="${p[0]}" y1="${p[1]}" x2="${q[0]}" y2="${q[1]}" class="edge ${b==='Amarr'?'route':''}"/><text class="edge-label" x="${mx}" y="${my-6}">${l}</text></g>`}).join('');
 const nodes=Object.entries(state.positions).map(([name,[x,y]])=>{const s=systems[name],selected=name===state.selectedSystem,r=name==='J154212'?34:26;return `<g class="node ${name==='J154212'?'home':''} ${selected?'selected':''}" data-system="${name}" transform="translate(${x} ${y})"><circle r="${r}"/><text x="${r+10}" y="-7">${name==='Amarr'?'K162 · Amarr':name}</text><text class="meta" x="${r+10}" y="10">${s.meta}</text><text class="value" x="${r+10}" y="27">${s.value}</text></g>`}).join('');
 return `<svg class="${cls}" viewBox="0 0 920 520" style="transform:translate(${state.pan.x}px,${state.pan.y}px) scale(${state.zoom});transform-origin:center" aria-label="Topological chain graph">${lines}${nodes}</svg>`;
}
