 'C3 PvE performance':{question:'Did v4 improve realized C3 performance?',cohorts:['All runs','C3 Shield v3','C3 Shield v4'],metrics:[['Median completion','−11%'],['Realized ISK / character-hour','+18%'],['Abort rate','−4 pp']],bars:[62,88,71,93],records:['RUN-881 · Frontier Barracks · 84M net','RUN-884 · Solar Cell · 91M net','RUN-889 · Frontier Barracks · aborted']},
 'Market fill performance':{question:'Which listings convert to realized cash efficiently?',cohorts:['All items','Gas products','Doctrine modules'],metrics:[['Median time-to-fill','2.4d'],['Realized margin','8.1%'],['Relist fees','−1.2%']],bars:[48,76,63,84],records:['SELL-221 · Fullerite-C32 · 61% sold','SELL-218 · Fuel Blocks · filled','SELL-214 · Shield module · relisted']},
 'Transport efficiency':{question:'Which routes and load compositions reduce operator burden?',cohorts:['All loads','Market HQ → staging','Staging → home'],metrics:[['Capacity utilization','64%'],['Median lead time','1.8d'],['Consolidation','2.3 POs/load']],bars:[52,64,81,72],records:['TL-208 · 3 PO lines · 36% capacity','TL-211 · staged · 82% capacity','TL-214 · 2 PO lines · 74% capacity']}
