function renderBriefEnhanced(){
 const feed=attention.map(a=>{const st=state.attentionState[a.id];return `<article class="attention-card ${a.level}"><div class="attention-status"><span>${st.status}</span>${st.until?`<small>until ${st.until}</small>`:''}</div><h3>${a.title}</h3><p>${a.body}</p><p class="source-condition">Source condition: ${a.id===1?'Ready hull count below doctrine target':a.id===2?'Extractor programs nearing expiry':'Required ESI scope missing'}</p><div class="attention-actions">${st.status==='RESOLVED'?'<span class="tag good">Auto-resolved when source cleared</span>':`<button data-attention-state="ack" data-id="${a.id}">Acknowledge</button><button data-attention-state="snooze" data-id="${a.id}">Snooze 2h</button><button data-attention-state="defer" data-id="${a.id}">Defer · review tomorrow</button>${a.id===2?`<button data-attention-state="resolve" data-id="${a.id}">Simulate source clear</button>`:''}`}</div></article>`}).join('');
 $('#main').innerHTML=`${head('Executive Brief','MAP-FIRST OPERATING PICTURE')}<div class="brief-grid">${mapPanel()}${panel('ATTENTION',`<div class="attention-list">${feed}</div>`,'attention','<small>State-backed lifecycle</small>')}${panel('ACTIVE CHARACTERS',`<div class="char-row">${[['Naffin McGreggor','Account 01','Astero · J154212'],['Naffin Minner','Account 02','Prospect · J172504'],['Renab Naf','Account 03 · Alpha','Svipul · J155310'],['Naffin Isktrad','Account 01','Mastodon · Amarr'],['Ollie Henbo','Account 02','Epithal · J154212']].map(c=>`<button class="char-card portrait-card" data-character="${c[0]}">${portrait(c[0])}<span><strong>${c[0]}</strong><small>${c[1]}</small><small class="status-pill">● ${c[2]}</small></span></button>`).join('')}</div>`,'characters','<small>Current sample activity</small>')}</div>`;
}
function persistMap(){try{localStorage.setItem('bastion.prototype.mapLayout',JSON.stringify({positions:state.positions,pan:state.pan}))}catch{}}
function bindEnhancedMap(){const stage=$('.chain-map-stage'),svg=stage?.querySelector('svg');if(!stage||!svg)return;let drag=null;stage.onpointerdown=e=>{if(e.target.closest('.node'))return;drag={kind:'pan',x:e.clientX,y:e.clientY,start:{...state.pan}};stage.setPointerCapture(e.pointerId)};stage.onpointermove=e=>{if(!drag||drag.kind!=='pan')return;state.pan={x:drag.start.x+e.clientX-drag.x,y:drag.start.y+e.clientY-drag.y};svg.style.transform=`translate(${state.pan.x}px,${state.pan.y}px) scale(${state.zoom})`};stage.onpointerup=()=>{if(drag?.kind==='pan')persistMap();drag=null};$$('.chain-map-stage .node').forEach(n=>{n.onpointerdown=e=>{e.stopPropagation();drag={kind:'node',name:n.dataset.system,x:e.clientX,y:e.clientY,pos:[...state.positions[n.dataset.system]]};n.setPointerCapture(e.pointerId)};n.onpointermove=e=>{if(drag?.kind!=='node'||drag.name!==n.dataset.system)return;const scale=920/svg.getBoundingClientRect().width;state.positions[drag.name]=[drag.pos[0]+(e.clientX-drag.x)*scale/state.zoom,drag.pos[1]+(e.clientY-drag.y)*scale/state.zoom];n.setAttribute('transform',`translate(${state.positions[drag.name][0]} ${state.positions[drag.name][1]})`)};n.onpointerup=()=>{state.selectedSystem=n.dataset.system;persistMap();render()};n.onclick=e=>e.stopPropagation()})}

Object.assign(renders,{brief:renderBriefEnhanced,chain:renderChain,accounts:renderAccounts,doctrines:renderDoctrines,inventory:renderInventory,market:renderMarket,procurement:renderProcurement,finance:renderFinance,knowledge:renderKnowledge,analytics:renderAnalytics,settings:renderSettings});
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),2200)}
$('#scrim').onclick=closeDrawer;const dlg=$('#searchDialog'),input=$('#searchInput'),results=$('#searchResults');function openSearch(){dlg.showModal();input.value='';renderSearch('');setTimeout(()=>input.focus(),20)}function renderSearch(q){const hits=searchIndex.filter(x=>(x[0]+' '+x[1]).toLowerCase().includes(q.toLowerCase()));results.innerHTML=hits.map((x,i)=>`<button class="search-result" data-result="${i}"><span>${x[0]}<small>${x[1]}</small></span><span>↗</span></button>`).join('')||'<p class="subtle">No prototype results.</p>';$$('[data-result]').forEach((b,i)=>b.onclick=()=>{const hit=hits[i];dlg.close();state.view=hit[2];render();setTimeout(()=>openObject(hit[3],hit[4]),0)})}$('#searchTrigger').onclick=openSearch;input.oninput=()=>renderSearch(input.value);document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}if(e.key==='Escape')closeDrawer()});render();
